// راهنما: این Type با نام «AuthTokens» شکل و مقادیر مجاز داده را برای TypeScript مشخص می‌کند و در زمان اجرا کد مستقلی تولید نمی‌کند.
type AuthTokens = { access_token?: string; refresh_token?: string; expires_in?: number; user?: { id?: string; email?: string }; code?: string; error?: string; error_description?: string; msg?: string; message?: string };

// راهنما: این تابع «json» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
function json(data: unknown, init: ResponseInit = {}) { /* راهنما: این دستور متغیر/ثابت «headers» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const headers = new Headers(init.headers); /* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «headers.set('content-type', 'application/json; charset=utf-8')». */ headers.set('content-type', 'application/json; charset=utf-8'); /* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «headers.set('cache-control','no-store')». */ headers.set('cache-control','no-store'); /* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «new Response(JSON.stringify(data), { ...init, headers })» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return new Response(JSON.stringify(data), { ...init, headers }); }
// راهنما: این تابع «parseCookies» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
function parseCookies(request: Request) { /* راهنما: این دستور متغیر/ثابت «result» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const result = new Map<string,string>(); /* راهنما: این دستور متغیر/ثابت «raw» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const raw=request.headers.get('cookie')??''; /* راهنما: این حلقه مجموعه‌ای از داده‌ها یا یک بازه را پیمایش می‌کند و منطق داخل بدنه را برای هر مرحله اجرا می‌کند. */ for(const part of raw.split(';')){/* راهنما: این دستور متغیر/ثابت «index» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const index=part.indexOf('=');/* راهنما: این شرط بررسی می‌کند آیا «index<0» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(index<0)/* راهنما: این دستور ادامه دستورات مرحله فعلی حلقه را رد می‌کند و به تکرار بعدی می‌رود. */ continue;/* راهنما: این دستور متغیر/ثابت «key» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const key=part.slice(0,index).trim();/* راهنما: این دستور متغیر/ثابت «value» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const value=part.slice(index+1).trim();/* راهنما: این شرط بررسی می‌کند آیا «key» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(key)/* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «result.set(key,decodeURIComponent(value))». */ result.set(key,decodeURIComponent(value));} /* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «result» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return result; }
// راهنما: این تابع «cookie» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
function cookie(name:string,value:string,maxAge:number){/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «`${name}=${encodeURIComponent(value)}; Path=/; HttpOnly; Secure; SameSite=…» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return `${name}=${encodeURIComponent(value)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`}
// راهنما: این تابع «clearCookie» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
function clearCookie(name:string){/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «`${name}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return `${name}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`}
// راهنما: این تابع «authHeaders» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
function authHeaders(request:Request,extra:HeadersInit={}){/* راهنما: این دستور متغیر/ثابت «headers» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const headers=new Headers(extra);/* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «headers.set('apikey',SUPABASE_PUBLISHABLE_KEY)». */ headers.set('apikey',SUPABASE_PUBLISHABLE_KEY);/* راهنما: این دستور متغیر/ثابت «ip» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const ip=request.headers.get('cf-connecting-ip');/* راهنما: این شرط بررسی می‌کند آیا «ip» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(ip)/* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «headers.set('x-forwarded-for',ip)». */ headers.set('x-forwarded-for',ip);/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «headers» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return headers;}
// راهنما: این تابع «readAuthResponse» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
async function readAuthResponse(response:Response){/* راهنما: این دستور متغیر/ثابت «data» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const data=(await response.json().catch(()=>({}))) as AuthTokens;/* راهنما: این شرط بررسی می‌کند آیا «!response.ok» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(!response.ok){/* راهنما: این دستور متغیر/ثابت «message» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const message=data.error_description??data.msg??data.message??data.error??'خطای احراز هویت.';/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «{ok:false as const,status:response.status,message,code:data.code}» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return{ok:false as const,status:response.status,message,code:data.code}}/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «{ok:true as const,data}» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return{ok:true as const,data}}
// راهنما: این تابع «withSessionCookies» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
function withSessionCookies(response:Response,tokens:AuthTokens){/* راهنما: این دستور متغیر/ثابت «headers» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const headers=new Headers(response.headers);/* راهنما: این شرط بررسی می‌کند آیا «tokens.access_token» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(tokens.access_token)/* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «headers.append('set-cookie',cookie(ACCESS_COOKIE,tokens.access_token,Math.max(60,Number(t…». */ headers.append('set-cookie',cookie(ACCESS_COOKIE,tokens.access_token,Math.max(60,Number(tokens.expires_in??3600))));/* راهنما: این شرط بررسی می‌کند آیا «tokens.refresh_token» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(tokens.refresh_token)/* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «headers.append('set-cookie',cookie(REFRESH_COOKIE,tokens.refresh_token,60*60*24*30))». */ headers.append('set-cookie',cookie(REFRESH_COOKIE,tokens.refresh_token,60*60*24*30));/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «new Response(response.body,{status:response.status,headers})» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return new Response(response.body,{status:response.status,headers})}
// راهنما: این تابع «passwordGrant» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
async function passwordGrant(request:Request,email:string,password:string){/* راهنما: این متغیر «response» نتیجه یا Promise یک درخواست شبکه را نگه می‌دارد. */ const response=await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`,{method:'POST',headers:authHeaders(request,{'content-type':'application/json'}),body:JSON.stringify({email,password})});/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «readAuthResponse(response)» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return readAuthResponse(response);}
// راهنما: این تابع «refreshSession» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
async function refreshSession(request:Request,refreshToken:string){/* راهنما: این متغیر «response» نتیجه یا Promise یک درخواست شبکه را نگه می‌دارد. */ const response=await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:authHeaders(request,{'content-type':'application/json'}),body:JSON.stringify({refresh_token:refreshToken})});/* راهنما: این دستور متغیر/ثابت «result» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const result=await readAuthResponse(response);/* راهنما: این شرط بررسی می‌کند آیا «!result.ok||!result.data.access_token» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(!result.ok||!result.data.access_token)/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «null» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return null;/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «result.data» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return result.data;}
// راهنما: این تابع «getAccessToken» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
async function getAccessToken(request:Request){/* راهنما: این دستور متغیر/ثابت «cookies» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const cookies=parseCookies(request);/* راهنما: این دستور متغیر/ثابت «accessToken» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const accessToken=cookies.get(ACCESS_COOKIE);/* راهنما: این دستور متغیر/ثابت «refreshToken» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const refreshToken=cookies.get(REFRESH_COOKIE);/* راهنما: این شرط بررسی می‌کند آیا «accessToken» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(accessToken){/* راهنما: این متغیر «check» نتیجه یا Promise یک درخواست شبکه را نگه می‌دارد. */ const check=await fetch(`${SUPABASE_URL}/auth/v1/user`,{headers:authHeaders(request,{authorization:`Bearer ${accessToken}`})});/* راهنما: این شرط بررسی می‌کند آیا «check.ok» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(check.ok)/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «{token:accessToken,refreshed:null as AuthTokens|null}» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return{token:accessToken,refreshed:null as AuthTokens|null};}/* راهنما: این شرط بررسی می‌کند آیا «refreshToken» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(refreshToken){/* راهنما: این دستور متغیر/ثابت «refreshed» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const refreshed=await refreshSession(request,refreshToken);/* راهنما: این شرط بررسی می‌کند آیا «refreshed?.access_token» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(refreshed?.access_token)/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «{token:refreshed.access_token,refreshed}» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return{token:refreshed.access_token,refreshed};}/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «null» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return null;}
// راهنما: این تابع «proxyFunction» یک بخش مستقل از منطق برنامه را تعریف می‌کند؛ ورودی‌ها را می‌گیرد و منطق داخل بدنه را اجرا می‌کند.
