async function proxyDiscordInteraction(request:Request,applicationId:string){/* راهنما: این دستور متغیر/ثابت «headers» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const headers=authHeaders(request,{accept:'application/json'});/* راهنما: این حلقه مجموعه‌ای از داده‌ها یا یک بازه را پیمایش می‌کند و منطق داخل بدنه را برای هر مرحله اجرا می‌کند. */ for(const name of ['content-type','x-signature-ed25519','x-signature-timestamp']){/* راهنما: این دستور متغیر/ثابت «value» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const value=request.headers.get(name);/* راهنما: این شرط بررسی می‌کند آیا «value» برقرار است؛ فقط در صورت درست بودن، شاخه مربوط اجرا می‌شود. */ if(value)/* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «headers.set(name,value)». */ headers.set(name,value);}/* راهنما: این دستور متغیر/ثابت «upstreamUrl» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const upstreamUrl=new URL(`${SUPABASE_URL}/functions/v1/discord-interactions/${encodeURIComponent(applicationId)}`);/* راهنما: این دستور متغیر/ثابت «body» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const body=await request.arrayBuffer();/* راهنما: این متغیر «upstream» نتیجه یا Promise یک درخواست شبکه را نگه می‌دارد. */ const upstream=await fetch(upstreamUrl.toString(),{method:'POST',headers,body});/* راهنما: این دستور متغیر/ثابت «responseHeaders» را تعریف می‌کند و مقدار موردنیاز این بخش از برنامه را نگه می‌دارد. */ const responseHeaders=new Headers(upstream.headers);/* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «responseHeaders.set('cache-control','no-store')». */ responseHeaders.set('cache-control','no-store');/* راهنما: این دستور یک عملیات اجرایی انجام می‌دهد: «responseHeaders.delete('set-cookie')». */ responseHeaders.delete('set-cookie');/* راهنما: این Return اجرای تابع را در این نقطه تمام می‌کند و «new Response(upstream.body,{status:upstream.status,headers:responseHeaders…» را به فراخواننده برمی‌گرداند؛ در کامپوننت React می‌تواند UI خروجی باشد. */ return new Response(upstream.body,{status:upstream.status,headers:responseHeaders});}

